function postDisplay(){document.getElementById("delete").style.display="none";document.getElementById("post").style.display="block";document.getElementById("check").style.display="none";document.getElementById("edit").style.display="none";hideDrawer();}
function checkDisplay(){document.getElementById("check").style.display="block";document.getElementById("post").style.display="none";document.getElementById("delete").style.display="none";document.getElementById("edit").style.display="none";hideDrawer();}
function editDisplay(){document.getElementById("edit").style.display="block";document.getElementById("post").style.display="none";document.getElementById("check").style.display="none";document.getElementById("delete").style.display="none";hideDrawer();}
function deleteDisplay(){document.getElementById("delete").style.display="block";document.getElementById("post").style.display="none";document.getElementById("check").style.display="none";document.getElementById("edit").style.display="none";hideDrawer();}
function doIt(e){var t=e.children[0].innerHTML,n=e.children[1].innerHTML,l=e.children[2].innerHTML,c=e.children[3].innerHTML,i=e.children[5].innerHTML,d=e.children[6].innerHTML,o=e.children[7].innerHTML;$.post("register2.php",{name:t,email:l,phone:n,address:c,birth:i,account:d,password:o},function(t){console.log(t),"success"==t?e.children[4].innerHTML="確認成功":"fail"==t?e.children[4].innerHTML="重整頁面再試一次！":e.children[4].innerHTML="重整頁面再試一次！"}),$.post("check2one.php",{account:d},function(t){console.log(t),"success"==t?e.children[4].innerHTML="確認成功":"fail"==t?e.children[4].innerHTML="重整頁面再試一次！":(t="not exist")&&(e.children[4].innerHTML="重整頁面再試一次！")})}
function denyIt(e){var t=e.children[6].innerHTML;$.post("check2one.php",{account:t},function(t){console.log(t),"success"==t?e.children[4].innerHTML="確認成功":"fail"==t?e.children[4].innerHTML="重整頁面再試一次！":(t="not exist")&&(e.children[4].innerHTML="重整頁面再試一次！")})}
function newArticle(){var e=document.getElementById("heading").value,t=document.getElementById("time").value,n=tinyMCE.activeEditor.getContent().toString(),c="";if(e.length<1||n.length<1)document.getElementById("sthEmpty").style.display="block",setTimeout('document.getElementById("sthEmpty").style.display="none"',3e3);else{document.getElementById("newest").checked&&(c=categoryDecider(0));document.getElementById("end").checked&&(c=categoryDecider(1));document.getElementById("competition").checked&&(c=categoryDecider(2));document.getElementById("activity").checked&&(c=categoryDecider(3));$.post("articleToDB.php",{category:c,heading:e,content:n,time:t},function(e){e=="success"?(document.getElementById("successArticle").style.display="block",document.getElementById("heading").value="",document.getElementById("time").value="",tinyMCE.activeEditor.setContent(""),setTimeout('document.getElementById("successArticle").style.display="none"',3e3)):(document.getElementById("failArticle").style.display="block",setTimeout('document.getElementById("failArticle").style.display="none"',3e3))})}}
function updateArticle(){var e=document.getElementById("e_heading").value,t=document.getElementById("e_time").value,n=tinyMCE.activeEditor.getContent().toString(),c="",tt=document.getElementById("edit_s").value;if(e.length<1||n.length<1)document.getElementById("e_sthEmpty").style.display="block",setTimeout('document.getElementById("e_sthEmpty").style.display="none"',3e3);else{document.getElementById("e_newest").checked&&(c=categoryDecider(0));document.getElementById("e_end").checked&&(c=categoryDecider(1));document.getElementById("e_competition").checked&&(c=categoryDecider(2));document.getElementById("e_activity").checked&&(c=categoryDecider(3));$.post("articleUpdate.php",{category:c,heading:e,content:n,time:t,timer:tt},function(e){e=="success"?(document.getElementById("e_successArticle").style.display="block",setTimeout('document.getElementById("e_successArticle").style.display="none"',3e3)):(document.getElementById("e_failArticle").style.display="block",setTimeout('document.getElementById("e_failArticle").style.display="none"',3e3))})}}
function categoryDecider(e){switch(e){case 0:return"一般消息";case 1:return"比賽成果";case 2:return"競賽資訊";case 3:return"球隊活動"}}
function deleteArticle(){$(".is-selected").each(function(){var e=$(this).attr("id");$.post("deleteArticle.php",{timer:$(this).attr("id")},function(t){console.log(t),console.log(e),"success"==t&&(document.getElementById(e).className="",document.getElementById(e).children[0].innerHTML="已刪除",document.getElementById(e).style.color="#9E9E9E",document.getElementById(e).children[1].style.textDecoration="line-through",document.getElementById(e).children[2].style.textDecoration="line-through",document.getElementById(e).children[3].style.textDecoration="line-through")})})}
